<!doctype html><html lang="es"><head><meta charset="utf-8"><style>@page{size:A5 portrait;margin:14mm}body{font-family:Arial;font-size:11px;color:#111}table{width:100%;border-collapse:collapse;margin:12px 0}td,th{border:1px solid #111;padding:7px}.head{background:#e2e8f0;font-weight:bold}.center{text-align:center}.sign{border:1px dashed #475569;min-height:100px;padding:10px}.muted{color:#64748b;font-size:9px}</style></head><body><h2 class="center">CONSTANCIA DE EJECUCIÓN — QR</h2><p class="center">Papeleta de salida N.° <b>{{ $papeleta->numero_papeleta }}</b></p><table><tr><td class="head">Servidor</td><td>{{ $papeleta->employee?->full_name }}</td></tr><tr><td class="head">DNI</td><td>{{ $papeleta->employee?->dni }}</td></tr><tr><td class="head">Motivo</td><td>{{ $papeleta->reason?->nombre }}</td></tr><tr><td class="head">Salida registrada por QR</td><td>{{ $papeleta->salida_real_at?->format('d/m/Y H:i:s') ?? 'Pendiente' }}</td></tr><tr><td class="head">Retorno registrado por QR</td><td>{{ $papeleta->retorno_real_at?->format('d/m/Y H:i:s') ?? 'Pendiente' }}</td></tr></table>@if($papeleta->reason?->tipo === 'comision')<h3>Constancia de entidad de destino</h3><div class="sign">@if($papeleta->destino_firmado_at)<b>{{ $papeleta->destino_firmante_nombre }}</b><br>{{ $papeleta->destino_firmante_cargo }}<br><span class="muted">Firmó en pantalla táctil el {{ $papeleta->destino_firmado_at->format('d/m/Y H:i:s') }}</span>@php($firmaPath = $papeleta->destino_firma_path ? storage_path('app/private/'.$papeleta->destino_firma_path) : null)@if($firmaPath && file_exists($firmaPath))<br><img src="data:image/png;base64,{{ base64_encode(file_get_contents($firmaPath)) }}" style="width:230px;max-height:75px">@endif @else Pendiente de firma de entidad destino. @endif</div>@endif<p class="muted center">Documento de trazabilidad operativa vinculado a la papeleta firmada digitalmente. Generado: {{ now()->format('d/m/Y H:i:s') }}</p></body></html>
